{
  "$schema": "https://static.modelcontextprotocol.io/schemas/2025-12-11/server.schema.json",
  "name": "io.github.runapi-builder/runapi-mcp",
  "description": "130+ AI models for image, video, music, and audio — 18 model families, one RunAPI account.",
  "repository": {
    "url": "https://github.com/runapi-ai/mcp",
    "source": "github"
  },
  "version": "0.1.16",
  "packages": [
    {
      "registryType": "npm",
      "identifier": "@runapi.ai/mcp",
      "version": "0.1.16",
      "transport": {
        "type": "stdio"
      },
      "environmentVariables": [
        {
          "description": "Optional RunAPI API key for headless hosts. Interactive MCP hosts can use the login tool, which writes shared RunAPI config.",
          "isRequired": false,
          "format": "string",
          "isSecret": true,
          "name": "RUNAPI_API_KEY"
        }
      ]
    }
  ]
}
